  ('Goal Line', 'Normal', 'PA Spot', 'Play Action'),
  ('Goal Line', 'Normal', 'PA Spot', 'Auto-tagged'),
  ('Goal Line', 'Normal', 'PA Sprint HB Flat', 'Play Action'),
  ('Goal Line', 'Normal', 'PA Sprint HB Flat', 'Auto-tagged'),
  ('Goal Line', 'Normal', 'PA Waggle', 'Play Action'),
  ('Goal Line', 'Normal', 'PA Waggle', 'Bootleg'),
  ('Goal Line', 'Normal', 'PA Waggle', 'Auto-tagged'),
  ('Goal Line', 'Normal', 'Power O', 'Run'),
  ('Goal Line', 'Normal', 'Power O', 'Power'),
  ('Goal Line', 'Normal', 'Power O', 'Auto-tagged'),
  ('Goal Line', 'Normal', 'QB Sneak', 'Run'),
  ('Goal Line', 'Normal', 'QB Sneak', 'QB Sneak'),
